   v[8] = (x[14] * x[7] + x[15] * x[8] + x[16] * x[9] + x[17] * x[10] + x[18] * x[11] + x[19] * x[12] + x[20] * x[13] - v[7] * v[3]) / v[4];
   v[9] = sqrt(1e-06 + x[14] * x[14] + x[15] * x[15] + x[16] * x[16] + x[17] * x[17] + x[18] * x[18] + x[19] * x[19] + x[20] * x[20] - v[7] * v[7] - v[8] * v[8]);
   v[10] = (x[35] * x[14] + x[36] * x[15] + x[37] * x[16] + x[38] * x[17] + x[39] * x[18] + x[40] * x[19] + x[41] * x[20] - v[1] * v[7] - v[5] * v[8]) / v[9];
