   v[13] = (x[21] * x[7] + x[22] * x[8] + x[23] * x[9] + x[24] * x[10] + x[25] * x[11] + x[26] * x[12] + x[27] * x[13] - v[12] * v[3]) / v[4];
   v[14] = (x[21] * x[14] + x[22] * x[15] + x[23] * x[16] + x[24] * x[17] + x[25] * x[18] + x[26] * x[19] + x[27] * x[20] - v[12] * v[7] - v[13] * v[8]) / v[9];
   v[15] = sqrt(1e-06 + x[21] * x[21] + x[22] * x[22] + x[23] * x[23] + x[24] * x[24] + x[25] * x[25] + x[26] * x[26] + x[27] * x[27] - v[12] * v[12] - v[13] * v[13] - v[14] * v[14]);
   v[16] = (x[35] * x[21] + x[36] * x[22] + x[37] * x[23] + x[38] * x[24] + x[39] * x[25] + x[40] * x[26] + x[41] * x[27] - v[1] * v[12] - v[5] * v[13] - v[10] * v[14]) / v[15];
