   v[12] = sqrt(1e-06 + x[3] * x[3] + x[10] * x[10] + x[17] * x[17] + x[24] * x[24] + x[31] * x[31] + x[38] * x[38] - v[9] * v[9] - v[10] * v[10] - v[11] * v[11]);
