   v[27] = (x[6] * x[0] + x[13] * x[7] + x[20] * x[14] + x[27] * x[21] + x[34] * x[28] + x[41] * x[35]) / v[0];
   v[28] = (x[6] * x[1] + x[13] * x[8] + x[20] * x[15] + x[27] * x[22] + x[34] * x[29] + x[41] * x[36] - v[27] * v[2]) / v[3];
   v[29] = (x[6] * x[2] + x[13] * x[9] + x[20] * x[16] + x[27] * x[23] + x[34] * x[30] + x[41] * x[37] - v[27] * v[5] - v[28] * v[6]) / v[7];
   v[30] = (x[6] * x[3] + x[13] * x[10] + x[20] * x[17] + x[27] * x[24] + x[34] * x[31] + x[41] * x[38] - v[27] * v[9] - v[28] * v[10] - v[29] * v[11]) / v[12];
   v[31] = (x[6] * x[4] + x[13] * x[11] + x[20] * x[18] + x[27] * x[25] + x[34] * x[32] + x[41] * x[39] - v[27] * v[14] - v[28] * v[15] - v[29] * v[16] - v[30] * v[17]) / v[18];
   v[32] = (x[6] * x[5] + x[13] * x[12] + x[20] * x[19] + x[27] * x[26] + x[34] * x[33] + x[41] * x[40] - v[27] * v[20] - v[28] * v[21] - v[29] * v[22] - v[30] * v[23] - v[31] * v[24]) / v[25];
   v[33] = sqrt(1e-06 + x[6] * x[6] + x[13] * x[13] + x[20] * x[20] + x[27] * x[27] + x[34] * x[34] + x[41] * x[41] - v[27] * v[27] - v[28] * v[28] - v[29] * v[29] - v[30] * v[30] - v[31] * v[31] - v[32] * v[32]);
